"""
MXFP4 GEMM: HIP C++ quant with INLINE e8m0_shuffle + gemm_a4w4_asm.

Key optimization: Fuses e8m0_shuffle into the HIP quant kernel, eliminating
a separate 12.9µs kernel launch. The quant kernel writes scales directly
in the shuffled layout expected by gemm_a4w4_asm.

Shuffle permutation: view(M//32, 2, 16, K_s//8, 2, 4).permute(0,3,5,2,4,1)
"""
import torch
import os
import ctypes
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_hip_lib = None
_hip_done = False
_config_cache: dict = {}

HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

#define BLOCK 256
#define GROUP_SIZE 32

// Compute the shuffled output index for an e8m0 scale byte.
// The shuffle permutation is:
//   view(sm//32, 2, 16, sn//8, 2, 4).permute(0, 3, 5, 2, 4, 1).contiguous().view(sm, sn)
//
// Input position: (row, col) in a (sm, sn) tensor with sm = padded M, sn = padded K//32
// The 6D decomposition of (row, col):
//   d0 = row / 32          (block of 32 rows)
//   d1 = (row % 32) / 16   (which half of the 32-row block: 0 or 1)
//   d2 = row % 16           (position within the 16-row half)
//   d3 = col / 8            (block of 8 columns)
//   d4 = (col % 8) / 4      (which half of the 8-col block: 0 or 1)
//   d5 = col % 4            (position within the 4-col half)
//
// After permute(0, 3, 5, 2, 4, 1), the output shape is:
//   (sm//32, sn//8, 4, 16, 2, 2)
// with output dims = (d0, d3, d5, d2, d4, d1)
//
// Output linear index = d0 * (sn//8 * 4 * 16 * 2 * 2) + d3 * (4 * 16 * 2 * 2)
//                      + d5 * (16 * 2 * 2) + d2 * (2 * 2) + d4 * 2 + d1
// Simplified: output = d0 * sn * 32 + d3 * 256 + d5 * 64 + d2 * 4 + d4 * 2 + d1

__device__ __forceinline__ int shuffle_index(int row, int col, int sm, int sn) {
    int d0 = row >> 5;           // row / 32
    int r32 = row & 31;          // row % 32
    int d1 = r32 >> 4;           // (row%32) / 16
    int d2 = r32 & 15;           // row % 16
    int d3 = col >> 3;           // col / 8
    int c8 = col & 7;            // col % 8
    int d4 = c8 >> 2;            // (col%8) / 4
    int d5 = c8 & 3;             // col % 4

    // Output shape after permute: (sm//32, sn//8, 4, 16, 2, 2)
    // Strides: (sn//8*4*16*2*2, 4*16*2*2, 16*2*2, 2*2, 2, 1)
    //        = (sn*32, 256, 64, 4, 2, 1)

    int sn8 = sn >> 3;  // sn / 8
    int stride_d0 = sn8 * 256;  // = sn * 32
    int flat = d0 * stride_d0 + d3 * 256 + d5 * 64 + d2 * 4 + d4 * 2 + d1;
    return flat;
}

__global__ void mxfp4_quant_fused_kernel(
    const __hip_bfloat16* __restrict__ A,
    unsigned char* __restrict__ A_q,
    unsigned char* __restrict__ A_scale_shuffled,
    int M, int K, int sm, int sn)
{
    const int LANES = 16;
    const int num_groups_per_row = K / GROUP_SIZE;
    const int total_groups = M * num_groups_per_row;

    int global_tid = blockIdx.x * BLOCK + threadIdx.x;
    int group_idx = global_tid / LANES;
    int lane = global_tid % LANES;

    if (group_idx >= total_groups) return;

    int row = group_idx / num_groups_per_row;
    int grp = group_idx % num_groups_per_row;

    int base = row * K + grp * GROUP_SIZE;
    float v0 = __bfloat162float(A[base + lane * 2]);
    float v1 = __bfloat162float(A[base + lane * 2 + 1]);

    __shared__ float red[BLOCK];
    int local_group = threadIdx.x / LANES;
    float local_max = fmaxf(fabsf(v0), fabsf(v1));
    red[threadIdx.x] = local_max;
    __syncthreads();

    int group_base = local_group * LANES;
    for (int stride = LANES / 2; stride > 0; stride >>= 1) {
