"""
MXFP4 GEMM: Production submission with first-call timing probe.

Identical to submission.py but prints per-shape timing on first call
to stdout (captured by benchmark harness).
"""
import torch
import os
import ctypes
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
