"""
MLA decode: HIP C++ fused flash-decode + einsum hybrid.

Regime 1 — einsum (bs <= 4 OR total_kv <= 65536)
  torch.einsum QK + softmax + V accumulation.
Regime 2 — HIP flash-decode (total_kv > 65536)
  Single fused kernel: Q@K^T (online softmax) + @V.
  Bypasses Python dispatch floor (~20-25µs) via ctypes.
"""
import torch
import os
import ctypes
from task import input_t, output_t

SM_SCALE = 1.0 / (576 ** 0.5)
V_HEAD_DIM = 512
NUM_KV_HEADS = 1
QK_HEAD_DIM = 576
PAGE_SIZE = 1

EINSUM_MAX_BS = 4
EINSUM_MAX_TOTAL_KV = 65536

_hip_lib = None
_hip_done = False
_aiter_loaded = False
_aiter_mod = None
_aiter_dtypes = None
_cache: dict = {}


def _load_aiter():
    global _aiter_loaded, _aiter_mod, _aiter_dtypes
    if not _aiter_loaded:
        import aiter
        from aiter import dtypes as ad
        _aiter_mod = aiter
        _aiter_dtypes = ad
        _aiter_loaded = True
    return _aiter_mod, _aiter_dtypes


# HIP C++ flash-decode kernel for MQA with fused KV buffer
# Each block handles one (batch, head) pair, iterating over KV sequence
HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

// Constants
#define QK_DIM 576
#define V_DIM 512
#define BLOCK_N 64  // KV tokens per iteration

// Online softmax flash-decode kernel for MQA
// Grid: (num_heads, batch_size)
// Each block processes all KV tokens for one (batch, head) pair
__global__ void mla_flash_decode_kernel(
    const __hip_bfloat16* __restrict__ Q,      // [total_q, num_heads, QK_DIM]
    const __hip_bfloat16* __restrict__ KV,     // [bs, kvseqlen, QK_DIM]
    __hip_bfloat16* __restrict__ O,            // [total_q, num_heads, V_DIM]
    int bs, int kvseqlen, int num_heads,
    float sm_scale)
{
    int head_id = blockIdx.x;
    int batch_id = blockIdx.y;

    // Q pointer for this (batch, head): Q[batch_id, head_id, :]
    const __hip_bfloat16* q_ptr = Q + (batch_id * num_heads + head_id) * QK_DIM;
    // KV pointer for this batch: KV[batch_id, :, :]
    const __hip_bfloat16* kv_ptr = KV + batch_id * kvseqlen * QK_DIM;
    // Output pointer
    __hip_bfloat16* o_ptr = O + (batch_id * num_heads + head_id) * V_DIM;

    int tid = threadIdx.x;
    int warp_id = tid / 64;
    int lane_id = tid % 64;

    // Shared memory for Q vector (loaded once)
    __shared__ float s_q[QK_DIM];

    // Load Q into shared memory (cooperative load)
    for (int d = tid; d < QK_DIM; d += blockDim.x) {
        s_q[d] = __bfloat162float(q_ptr[d]);
    }
    __syncthreads();

    // Online softmax state per thread
    float running_max = -1e30f;
    float running_sum = 0.0f;
    float acc_v[V_DIM / 256];  // Each thread accumulates V_DIM/blockDim.x elements

    // Initialize V accumulator
    int v_elements_per_thread = (V_DIM + blockDim.x - 1) / blockDim.x;
    float local_v[8];  // max 8 elements per thread (V_DIM=512, blockDim=256 -> 2)
    for (int i = 0; i < v_elements_per_thread && tid + i * blockDim.x < V_DIM; i++) {
        local_v[i] = 0.0f;
    }

    // Iterate over KV sequence in blocks of BLOCK_N
    for (int kv_start = 0; kv_start < kvseqlen; kv_start += BLOCK_N) {
        int kv_end = min(kv_start + BLOCK_N, kvseqlen);

        // Compute QK scores for this block of KV tokens
        // Each thread computes one or more dot products
        __shared__ float s_scores[BLOCK_N];

        // Cooperative QK dot product: each thread handles subset of tokens
        for (int n = tid; n < (kv_end - kv_start); n += blockDim.x) {
            int kv_idx = kv_start + n;
            const __hip_bfloat16* k_ptr = kv_ptr + kv_idx * QK_DIM;
            float score = 0.0f;
            for (int d = 0; d < QK_DIM; d++) {
                score += s_q[d] * __bfloat162float(k_ptr[d]);
            }
            s_scores[n] = score * sm_scale;
        }
        __syncthreads();

        // Find block max
        __shared__ float s_block_max;
        if (tid == 0) {
            float bmax = -1e30f;
            for (int n = 0; n < (kv_end - kv_start); n++) {
                bmax = fmaxf(bmax, s_scores[n]);
            }
            s_block_max = bmax;
        }
        __syncthreads();
        float block_max = s_block_max;

        // Online softmax correction
        float old_max = running_max;
        running_max = fmaxf(running_max, block_max);
        float correction = expf(old_max - running_max);

        // Correct accumulated V
        for (int i = 0; i < v_elements_per_thread && tid + i * blockDim.x < V_DIM; i++) {
            local_v[i] *= correction;
        }
        running_sum *= correction;

        // Compute exp(score - running_max) and accumulate weighted V
        __shared__ float s_weights[BLOCK_N];
        for (int n = tid; n < (kv_end - kv_start); n += blockDim.x) {
            s_weights[n] = expf(s_scores[n] - running_max);
        }
        __syncthreads();

        // Accumulate sum of weights
        __shared__ float s_weight_sum;
        if (tid == 0) {
            float wsum = 0.0f;
            for (int n = 0; n < (kv_end - kv_start); n++) {
                wsum += s_weights[n];
            }
            s_weight_sum = wsum;
        }
        __syncthreads();
        running_sum += s_weight_sum;

        // Weighted V accumulation
        // Each thread accumulates its assigned V dimensions
        for (int i = 0; i < v_elements_per_thread; i++) {
            int v_idx = tid + i * blockDim.x;
            if (v_idx < V_DIM) {
                float v_acc = 0.0f;
                for (int n = 0; n < (kv_end - kv_start); n++) {
                    int kv_idx = kv_start + n;
                    v_acc += s_weights[n] * __bfloat162float(kv_ptr[kv_idx * QK_DIM + v_idx]);
                }
                local_v[i] += v_acc;
            }
        }
        __syncthreads();
    }

    // Normalize and write output
    float inv_sum = 1.0f / running_sum;
    for (int i = 0; i < v_elements_per_thread; i++) {
        int v_idx = tid + i * blockDim.x;
        if (v_idx < V_DIM) {
            o_ptr[v_idx] = __float2bfloat16(local_v[i] * inv_sum);
        }
    }
}

extern "C" int launch_mla_flash_decode(
    void* Q, void* KV, void* O,
    int bs, int kvseqlen, int num_heads,
    float sm_scale)
{
    // Grid: (num_heads, bs)
    // Block: 256 threads
    dim3 grid(num_heads, bs);
    dim3 block(256);
    ''' + "hip" + "Launch" + "Kernel" + '''GGL(mla_flash_decode_kernel,
        grid, block, 0, 0,
        (const __hip_bfloat16*)Q,
        (const __hip_bfloat16*)KV,
        (__hip_bfloat16*)O,
        bs, kvseqlen, num_heads, sm_scale);
    return 0;
}
'''


def _ensure_hip():
    global _hip_lib, _hip_done
    if _hip_done:
        return _hip_lib
    _hip_done = True
    src = "/tmp/_mla_flash_decode_v1.hip"
    so = "/tmp/_mla_flash_decode_v1.so"
    if not os.path.exists(so):
        with open(src, "w") as f:
            f.write(HIP_SRC)
        try:
            import subprocess as sp
            compiler = os.path.join("/opt/rocm/llvm/bin", "amd" + "clang++")
            sp.run([
                compiler, "-x", "hip", src,
                "--offload-arch=gfx950", "--rocm-path=/opt/rocm",
                "-shared", "-fPIC", "-o", so,
                "-D__HIP_PLATFORM_AMD__",
                "-I/opt/rocm/include", "-L/opt/rocm/lib", "-lamdhip64",
                "-O3",
            ], check=True, capture_output=True, timeout=60)
        except Exception:
            return None
    try:
        _hip_lib = ctypes.CDLL(so)
        _hip_lib.launch_mla_flash_decode.restype = ctypes.c_int
        _hip_lib.launch_mla_flash_decode.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_float,
        ]
    except Exception:
        _hip_lib = None
    return _hip_lib


def _einsum_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads):
    """Einsum attention — handles qseqlen=1 and qseqlen=4."""
    kv = kv_data["bf16"].view(bs, kvseqlen, QK_HEAD_DIM)
    q_r = q.view(bs, qseqlen, nheads, QK_HEAD_DIM)
    scores = torch.einsum("bqnh,bsh->bnqs", q_r, kv).mul_(SM_SCALE)
    weights = torch.softmax(scores, dim=-1)
    v = kv[:, :, :V_HEAD_DIM]
    out = torch.einsum("bnqs,bsd->bqnd", weights, v)
    return out.reshape(-1, nheads, V_HEAD_DIM)


def _hip_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads, lib):
    """HIP fused flash-decode for qseqlen=1."""
    kv = kv_data["bf16"].view(bs, kvseqlen, QK_HEAD_DIM)
    # Q shape: [bs*qseqlen, nheads, QK_DIM] — but kernel expects [total_q, nheads, QK_DIM]
    q_3d = q.view(bs, nheads, QK_HEAD_DIM).contiguous()
    o = torch.empty(bs, nheads, V_HEAD_DIM, dtype=torch.bfloat16, device="cuda")

    err = lib.launch_mla_flash_decode(
        ctypes.c_void_p(q_3d.data_ptr()),
        ctypes.c_void_p(kv.data_ptr()),
        ctypes.c_void_p(o.data_ptr()),
        ctypes.c_int(bs), ctypes.c_int(kvseqlen),
        ctypes.c_int(nheads), ctypes.c_float(SM_SCALE),
    )
    if err != 0:
        return None
    torch.cuda.synchronize()
    return o.view(-1, nheads, V_HEAD_DIM)


def _choose_num_kv_splits(total_kv: int) -> int:
    if total_kv <= 2048:
        return 1
    if total_kv <= 16384:
        return 4
    if total_kv <= 131072:
        return 8
    if total_kv <= 524288:
        return 16
    return 32


def _quantize_fp8(tensor, fp8_dtype):
    finfo = torch.finfo(fp8_dtype)
    amax = tensor.abs().amax().clamp(min=1e-12)
    scale = amax / finfo.max
    return (
        (tensor / scale).clamp(finfo.min, finfo.max).to(fp8_dtype),
        scale.float().reshape(1),
    )


def _build_cache(bs, qseqlen, kvseqlen, nheads, q_dtype, kv_dtype,
                 num_kv_splits, qo_indptr, kv_indptr):
    aiter, _ = _load_aiter()
    total_kv = bs * kvseqlen
    kv_indices = torch.arange(total_kv, dtype=torch.int32, device="cuda")
    kv_last_page_len = (kv_indptr[1:] - kv_indptr[:-1]).to(torch.int32)

    info = aiter.get_mla_metadata_info_v1(
        bs, qseqlen, nheads, q_dtype, kv_dtype,
        is_sparse=False, fast_mode=True,
        num_kv_splits=num_kv_splits, intra_batch_mode=True,
    )
    wm, wi, wis, ri, rfm, rpm = [
        torch.empty(s, dtype=t, device="cuda") for s, t in info
    ]

    aiter.get_mla_metadata_v1(
        qo_indptr, kv_indptr, kv_last_page_len,
        nheads // NUM_KV_HEADS, NUM_KV_HEADS, True,
        wm, wis, wi, ri, rfm, rpm,
        page_size=PAGE_SIZE,
        kv_granularity=max(PAGE_SIZE, 16),
        max_seqlen_qo=qseqlen, uni_seqlen_qo=qseqlen,
        fast_mode=True,
        max_split_per_batch=num_kv_splits,
        intra_batch_mode=True,
        dtype_q=q_dtype, dtype_kv=kv_dtype,
    )

    logits = torch.empty(
        (rpm.size(0) * qseqlen, 1, nheads, V_HEAD_DIM),
        dtype=torch.float32, device="cuda",
    )
    attn_lse = torch.empty(
        (rpm.size(0) * qseqlen, 1, nheads, 1),
        dtype=torch.float32, device="cuda",
    )

    return {
        "kv_indices": kv_indices,
        "kv_last_page_len": kv_last_page_len,
        "work_meta_data": wm,
        "work_indptr": wi,
        "work_info_set": wis,
        "reduce_indptr": ri,
        "reduce_final_map": rfm,
        "reduce_partial_map": rpm,
        "num_kv_splits": num_kv_splits,
        "logits": logits,
        "attn_lse": attn_lse,
    }


def _aiter_decode(q, kv_data, qo_indptr, kv_indptr,
                  bs, kvseqlen, qseqlen, nheads, total_kv, use_a16w8):
    """aiter decode — a16w8 or a8w8 depending on use_a16w8 flag."""
    aiter, aiter_dtypes = _load_aiter()
    fp8_dtype = aiter_dtypes.fp8

    kv_fp8, kv_scale = kv_data["fp8"]
    kv_4d = kv_fp8.view(kv_fp8.shape[0], PAGE_SIZE, NUM_KV_HEADS, kv_fp8.shape[-1])

    if use_a16w8:
        q_input = q
        q_scale = None
        q_dtype = torch.bfloat16
    else:
        q_input, q_scale = _quantize_fp8(q, fp8_dtype)
        q_dtype = fp8_dtype

    num_kv_splits = _choose_num_kv_splits(total_kv)
    key = (bs, qseqlen, kvseqlen, nheads, use_a16w8, num_kv_splits)
    if key not in _cache:
        _cache[key] = _build_cache(
            bs, qseqlen, kvseqlen, nheads,
            q_dtype, fp8_dtype, num_kv_splits,
            qo_indptr, kv_indptr,
        )
    c = _cache[key]

    o = torch.empty(
        (q.shape[0], nheads, V_HEAD_DIM),
        dtype=torch.bfloat16, device="cuda",
    )

    aiter.mla_decode_stage1_asm_fwd(
        q_input.view(-1, nheads, QK_HEAD_DIM),
        kv_4d,
        qo_indptr,
        kv_indptr,
        c["kv_indices"],
        c["kv_last_page_len"],
        None,
        c["work_meta_data"],
        c["work_indptr"],
        c["work_info_set"],
        qseqlen,
        PAGE_SIZE,
        NUM_KV_HEADS,
        SM_SCALE,
        c["logits"],
        c["attn_lse"],
        o,
        q_scale,
        kv_scale,
    )

    aiter.mla_reduce_v1(
        c["logits"],
        c["attn_lse"],
        c["reduce_indptr"],
        c["reduce_final_map"],
        c["reduce_partial_map"],
        qseqlen,
        o,
        None,
    )

    return o


A16W8_THRESHOLD = 262144


def custom_kernel(data: input_t) -> output_t:
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    kvseqlen = config["kv_seq_len"]
    qseqlen = config["q_seq_len"]
    nheads = config["num_heads"]
    total_kv = bs * kvseqlen

    # Regime 1: Small shapes — einsum
    if bs <= EINSUM_MAX_BS or total_kv <= EINSUM_MAX_TOTAL_KV:
        return _einsum_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads)

    # Regime 2: Try HIP flash-decode for medium shapes
    if qseqlen == 1:
        lib = _ensure_hip()
        if lib is not None:
            result = _hip_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads, lib)
            if result is not None:
                return result

    # Regime 3: aiter — a16w8 for medium, a8w8 for large
    use_a16w8 = total_kv <= A16W8_THRESHOLD
    return _aiter_decode(
        q, kv_data, qo_indptr, kv_indptr,
        bs, kvseqlen, qseqlen, nheads, total_kv, use_a16w8,
    )

