"""
MLA decode: HIP C++ optimized flash-decode v2 + einsum hybrid.

v2 optimizations over v1:
1. Warp-level parallel QK dot product (64-wide shuffle reduce)
   - Each lane: 9 FMA + 6 shuffles instead of 576 serial FMAs
2. Parallel block-max and weight-sum via warp reductions
   - Replaces single-thread-0 serial scans
3. Vectorized bf16 loads (float2 = 4 bf16 values at once)
4. Removed torch.cuda.synchronize() — stream ordering suffices
5. Multiple warps process different KV tokens in parallel

Grid: (num_heads, batch_size), Block: 256 threads (4 warps of 64)
Each warp processes one KV token at a time — 4 tokens in parallel.
"""
import torch
import os
import ctypes
from task import input_t, output_t

SM_SCALE = 1.0 / (576 ** 0.5)
V_HEAD_DIM = 512
NUM_KV_HEADS = 1
QK_HEAD_DIM = 576
PAGE_SIZE = 1

EINSUM_MAX_BS = 4
EINSUM_MAX_TOTAL_KV = 65536

_hip_lib = None
_hip_done = False
_aiter_loaded = False
_aiter_mod = None
_aiter_dtypes = None
_cache: dict = {}


def _load_aiter():
    global _aiter_loaded, _aiter_mod, _aiter_dtypes
    if not _aiter_loaded:
        import aiter
        from aiter import dtypes as ad
        _aiter_mod = aiter
        _aiter_dtypes = ad
        _aiter_loaded = True
    return _aiter_mod, _aiter_dtypes


# Optimized HIP C++ flash-decode kernel v2
# Key: warp-level parallel dot product + parallel reductions
HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

#define QK_DIM 576
#define V_DIM 512
#define WARP_SIZE 64
#define NUM_WARPS 4
#define BLOCK_SIZE (WARP_SIZE * NUM_WARPS)
#define BLOCK_N 4  // KV tokens processed in parallel (one per warp)

// Elements per lane for QK dot product: ceil(576/64) = 9
#define QK_PER_LANE 9
// Elements per thread for V accumulation: 512/256 = 2
#define V_PER_THREAD 2

// Warp-level sum reduction via butterfly shuffle
__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        val += __shfl_xor(val, offset, WARP_SIZE);
    }
    return val;
}

// Warp-level max reduction via butterfly shuffle
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
