"""
MLA decode: HIP C++ optimized flash-decode v2 + einsum hybrid.

v2 optimizations over v1:
1. Warp-level parallel QK dot product (64-wide shuffle reduce)
   - Each lane: 9 FMA + 6 shuffles instead of 576 serial FMAs
2. Parallel block-max and weight-sum via warp reductions
   - Replaces single-thread-0 serial scans
3. Vectorized bf16 loads (float2 = 4 bf16 values at once)
4. Removed torch.cuda.synchronize() — stream ordering suffices
5. Multiple warps process different KV tokens in parallel

Grid: (num_heads, batch_size), Block: 256 threads (4 warps of 64)
Each warp processes one KV token at a time — 4 tokens in parallel.
"""
import torch
import os
import ctypes
from task import input_t, output_t

SM_SCALE = 1.0 / (576 ** 0.5)
V_HEAD_DIM = 512
NUM_KV_HEADS = 1
QK_HEAD_DIM = 576
PAGE_SIZE = 1

EINSUM_MAX_BS = 4
EINSUM_MAX_TOTAL_KV = 65536

_hip_lib = None
_hip_done = False
_aiter_loaded = False
_aiter_mod = None
_aiter_dtypes = None
