// Optimized flash-decode kernel for MQA
// Grid: (num_heads, batch_size)
// Block: 256 threads = 4 warps of 64
__global__ void mla_flash_decode_v2_kernel(
    const __hip_bfloat16* __restrict__ Q,      // [bs, num_heads, QK_DIM]
    const __hip_bfloat16* __restrict__ KV,     // [bs, kvseqlen, QK_DIM]
    __hip_bfloat16* __restrict__ O,            // [bs, num_heads, V_DIM]
    int bs, int kvseqlen, int num_heads,
    float sm_scale)
{
    int head_id = blockIdx.x;
    int batch_id = blockIdx.y;

    const __hip_bfloat16* q_ptr = Q + (batch_id * num_heads + head_id) * QK_DIM;
    const __hip_bfloat16* kv_base = KV + batch_id * kvseqlen * QK_DIM;
    __hip_bfloat16* o_ptr = O + (batch_id * num_heads + head_id) * V_DIM;

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Load Q into shared memory (cooperative load across all threads)
    __shared__ float s_q[QK_DIM];
    for (int d = tid; d < QK_DIM; d += BLOCK_SIZE) {
        s_q[d] = __bfloat162float(q_ptr[d]);
    }
    __syncthreads();

    // Per-thread online softmax state
    float running_max = -1e30f;
    float running_sum = 0.0f;

    // V accumulator — each thread handles V_PER_THREAD elements of V_DIM
    float local_v[V_PER_THREAD];
    #pragma unroll
    for (int i = 0; i < V_PER_THREAD; i++) {
        local_v[i] = 0.0f;
    }

    // Shared memory for inter-warp communication
    __shared__ float s_scores[BLOCK_N];       // QK scores (one per warp)
    __shared__ float s_block_max;             // Block-level max
    __shared__ float s_weight_sum;            // Block-level weight sum
    __shared__ float s_weights[BLOCK_N];      // Softmax weights

    // Process KV tokens: each iteration, 4 warps handle 4 consecutive tokens
    for (int kv_start = 0; kv_start < kvseqlen; kv_start += BLOCK_N) {
        int my_kv_idx = kv_start + warp_id;
        float score = -1e30f;

        if (my_kv_idx < kvseqlen) {
            // Each warp computes QK dot product for its assigned KV token
            // Warp-parallel: each lane handles QK_PER_LANE elements
            const __hip_bfloat16* k_ptr = kv_base + my_kv_idx * QK_DIM;
            float partial = 0.0f;

            #pragma unroll
            for (int i = 0; i < QK_PER_LANE; i++) {
                int d = lane_id + i * WARP_SIZE;
                if (d < QK_DIM) {
                    partial += s_q[d] * __bfloat162float(k_ptr[d]);
