        int valid_n = min(BLOCK_N, kvseqlen - kv_start);
        if (tid == 0) {
            float bmax = -1e30f;
            for (int n = 0; n < valid_n; n++) {
                bmax = fmaxf(bmax, s_scores[n]);
            }
            s_block_max = bmax;
        }
        __syncthreads();

        float block_max = s_block_max;

        // Online softmax correction
        float old_max = running_max;
        running_max = fmaxf(running_max, block_max);
        float correction = expf(old_max - running_max);

        // Correct accumulated V and running sum
        #pragma unroll
        for (int i = 0; i < V_PER_THREAD; i++) {
            local_v[i] *= correction;
        }
        running_sum *= correction;

        // Compute softmax weights
        if (tid == 0) {
            float wsum = 0.0f;
            for (int n = 0; n < valid_n; n++) {
                float w = expf(s_scores[n] - running_max);
                s_weights[n] = w;
                wsum += w;
            }
            // Zero out invalid slots
            for (int n = valid_n; n < BLOCK_N; n++) {
                s_weights[n] = 0.0f;
            }
            s_weight_sum = wsum;
        }
        __syncthreads();

        running_sum += s_weight_sum;

        // Weighted V accumulation
        // Each thread accumulates its assigned V dimensions across all valid tokens
        #pragma unroll
        for (int i = 0; i < V_PER_THREAD; i++) {
            int v_idx = tid + i * BLOCK_SIZE;
            if (v_idx < V_DIM) {
                float v_acc = 0.0f;
                #pragma unroll
                for (int n = 0; n < BLOCK_N; n++) {
                    if (kv_start + n < kvseqlen) {
                        v_acc += s_weights[n] *
                            __bfloat162float(kv_base[(kv_start + n) * QK_DIM + v_idx]);
                    }
                }
                local_v[i] += v_acc;
            }
        }
        __syncthreads();
    }

    // Normalize and write output
    float inv_sum = (running_sum > 0.0f) ? (1.0f / running_sum) : 0.0f;
    #pragma unroll
    for (int i = 0; i < V_PER_THREAD; i++) {
        int v_idx = tid + i * BLOCK_SIZE;
        if (v_idx < V_DIM) {
            o_ptr[v_idx] = __float2bfloat16(local_v[i] * inv_sum);
        }
