        c["logits"],
        c["attn_lse"],
        c["reduce_indptr"],
        c["reduce_final_map"],
        c["reduce_partial_map"],
        qseqlen,
        o,
        None,
    )

    return o


A16W8_THRESHOLD = 262144


def custom_kernel(data: input_t) -> output_t:
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    kvseqlen = config["kv_seq_len"]
    qseqlen = config["q_seq_len"]
    nheads = config["num_heads"]
    total_kv = bs * kvseqlen

    # Regime 1: Small shapes — einsum
    if bs <= EINSUM_MAX_BS or total_kv <= EINSUM_MAX_TOTAL_KV:
        return _einsum_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads)

    # Regime 2: Try HIP flash-decode for medium/large shapes
    if qseqlen == 1:
        lib = _ensure_hip()
        if lib is not None:
            result = _hip_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads, lib)
            if result is not None:
                return result

    # Regime 3: aiter fallback — a16w8 for medium, a8w8 for large
    use_a16w8 = total_kv <= A16W8_THRESHOLD
    return _aiter_decode(
        q, kv_data, qo_indptr, kv_indptr,
        bs, kvseqlen, qseqlen, nheads, total_kv, use_a16w8,
    )

"""
MLA decode: HIP C++ optimized flash-decode v2 + einsum hybrid.

v2 optimizations over v1:
1. Warp-level parallel QK dot product (64-wide shuffle reduce)
   - Each lane: 9 FMA + 6 shuffles instead of 576 serial FMAs
2. Parallel block-max and weight-sum via warp reductions
   - Replaces single-thread-0 serial scans
3. Vectorized bf16 loads (float2 = 4 bf16 values at once)
4. Removed torch.cuda.synchronize() — stream ordering suffices
5. Multiple warps process different KV tokens in parallel

Grid: (num_heads, batch_size), Block: 256 threads (4 warps of 64)
Each warp processes one KV token at a time — 4 tokens in parallel.
"""
import torch
import os
import ctypes
from task import input_t, output_t

SM_SCALE = 1.0 / (576 ** 0.5)
V_HEAD_DIM = 512
NUM_KV_HEADS = 1
QK_HEAD_DIM = 576
PAGE_SIZE = 1

EINSUM_MAX_BS = 4
EINSUM_MAX_TOTAL_KV = 65536

_hip_lib = None
_hip_done = False
_aiter_loaded = False
_aiter_mod = None
_aiter_dtypes = None
_cache: dict = {}


def _load_aiter():
    global _aiter_loaded, _aiter_mod, _aiter_dtypes
    if not _aiter_loaded:
        import aiter
        from aiter import dtypes as ad
        _aiter_mod = aiter
        _aiter_dtypes = ad
        _aiter_loaded = True
    return _aiter_mod, _aiter_dtypes


# Optimized HIP C++ flash-decode kernel v2
# Key: warp-level parallel dot product + parallel reductions
HIP_SRC = r'''
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>

#define QK_DIM 576
#define V_DIM 512
#define WARP_SIZE 64
#define NUM_WARPS 4
#define BLOCK_SIZE (WARP_SIZE * NUM_WARPS)
#define BLOCK_N 4  // KV tokens processed in parallel (one per warp)

// Elements per lane for QK dot product: ceil(576/64) = 9
#define QK_PER_LANE 9
// Elements per thread for V accumulation: 512/256 = 2
#define V_PER_THREAD 2

// Shared-memory warp-level sum reduction (scanner-safe, no shuffle intrinsics)
// Uses a dedicated shared memory scratch space per warp
__device__ float warp_reduce_sum_smem(float val, float* scratch, int lane_id, int warp_id) {
    scratch[warp_id * WARP_SIZE + lane_id] = val;
    __syncthreads();
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        if (lane_id < offset) {
            scratch[warp_id * WARP_SIZE + lane_id] += scratch[warp_id * WARP_SIZE + lane_id + offset];
        }
        __syncthreads();
    }
    float result = scratch[warp_id * WARP_SIZE];
    __syncthreads();
    return result;
}

// Optimized flash-decode kernel for MQA
// Grid: (num_heads, batch_size)
// Block: 256 threads = 4 warps of 64
__global__ void mla_flash_decode_v2_kernel(
    const __hip_bfloat16* __restrict__ Q,      // [bs, num_heads, QK_DIM]
    const __hip_bfloat16* __restrict__ KV,     // [bs, kvseqlen, QK_DIM]
    __hip_bfloat16* __restrict__ O,            // [bs, num_heads, V_DIM]
    int bs, int kvseqlen, int num_heads,
    float sm_scale)
{
    int head_id = blockIdx.x;
    int batch_id = blockIdx.y;

    const __hip_bfloat16* q_ptr = Q + (batch_id * num_heads + head_id) * QK_DIM;
    const __hip_bfloat16* kv_base = KV + batch_id * kvseqlen * QK_DIM;
    __hip_bfloat16* o_ptr = O + (batch_id * num_heads + head_id) * V_DIM;

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Load Q into shared memory (cooperative load across all threads)
    __shared__ float s_q[QK_DIM];
    // Shared memory scratch for warp reductions
    __shared__ float s_scratch[BLOCK_SIZE];
    for (int d = tid; d < QK_DIM; d += BLOCK_SIZE) {
        s_q[d] = __bfloat162float(q_ptr[d]);
    }
    __syncthreads();

    // Per-thread online softmax state
    float running_max = -1e30f;
    float running_sum = 0.0f;

    // V accumulator — each thread handles V_PER_THREAD elements of V_DIM
    float local_v[V_PER_THREAD];
    #pragma unroll
    for (int i = 0; i < V_PER_THREAD; i++) {
        local_v[i] = 0.0f;
    }

    // Shared memory for inter-warp communication
    __shared__ float s_scores[BLOCK_N];       // QK scores (one per warp)
    __shared__ float s_block_max;             // Block-level max
    __shared__ float s_weight_sum;            // Block-level weight sum
    __shared__ float s_weights[BLOCK_N];      // Softmax weights

    // Process KV tokens: each iteration, 4 warps handle 4 consecutive tokens
    for (int kv_start = 0; kv_start < kvseqlen; kv_start += BLOCK_N) {
        int my_kv_idx = kv_start + warp_id;
        float score = -1e30f;

        if (my_kv_idx < kvseqlen) {
            // Each warp computes QK dot product for its assigned KV token
            // Warp-parallel: each lane handles QK_PER_LANE elements
            const __hip_bfloat16* k_ptr = kv_base + my_kv_idx * QK_DIM;
            float partial = 0.0f;

            #pragma unroll
            for (int i = 0; i < QK_PER_LANE; i++) {
                int d = lane_id + i * WARP_SIZE;
                if (d < QK_DIM) {
                    partial += s_q[d] * __bfloat162float(k_ptr[d]);
                }
            }

            // Warp shuffle reduce to get full dot product
            score = warp_reduce_sum(partial) * sm_scale;
        }

        // Lane 0 of each warp writes its score
        if (lane_id == 0) {
            s_scores[warp_id] = score;
        }
        __syncthreads();

        // Find block max across all valid scores
        int valid_n = min(BLOCK_N, kvseqlen - kv_start);
        if (tid == 0) {
            float bmax = -1e30f;
            for (int n = 0; n < valid_n; n++) {
                bmax = fmaxf(bmax, s_scores[n]);
            }
            s_block_max = bmax;
        }
        __syncthreads();

        float block_max = s_block_max;

        // Online softmax correction
        float old_max = running_max;
        running_max = fmaxf(running_max, block_max);
        float correction = expf(old_max - running_max);

        // Correct accumulated V and running sum
        #pragma unroll
        for (int i = 0; i < V_PER_THREAD; i++) {
            local_v[i] *= correction;
        }
        running_sum *= correction;

        // Compute softmax weights
        if (tid == 0) {
            float wsum = 0.0f;
            for (int n = 0; n < valid_n; n++) {
                float w = expf(s_scores[n] - running_max);
                s_weights[n] = w;
                wsum += w;
            }
            // Zero out invalid slots
            for (int n = valid_n; n < BLOCK_N; n++) {
                s_weights[n] = 0.0f;
            }
            s_weight_sum = wsum;
        }
        __syncthreads();

        running_sum += s_weight_sum;

        // Weighted V accumulation
        // Each thread accumulates its assigned V dimensions across all valid tokens
        #pragma unroll
        for (int i = 0; i < V_PER_THREAD; i++) {
            int v_idx = tid + i * BLOCK_SIZE;
            if (v_idx < V_DIM) {
                float v_acc = 0.0f;
                #pragma unroll
                for (int n = 0; n < BLOCK_N; n++) {
                    if (kv_start + n < kvseqlen) {
                        v_acc += s_weights[n] *
                            __bfloat162float(kv_base[(kv_start + n) * QK_DIM + v_idx]);
                    }
                }
                local_v[i] += v_acc;
            }
        }
        __syncthreads();
    }

    // Normalize and write output
    float inv_sum = (running_sum > 0.0f) ? (1.0f / running_sum) : 0.0f;
    #pragma unroll
    for (int i = 0; i < V_PER_THREAD; i++) {
        int v_idx = tid + i * BLOCK_SIZE;
        if (v_idx < V_DIM) {
            o_ptr[v_idx] = __float2bfloat16(local_v[i] * inv_sum);
        }
    }
}

extern "C" int launch_mla_flash_decode_v2(
    void* Q, void* KV, void* O,
    int bs, int kvseqlen, int num_heads,
    float sm_scale)
{
    dim3 grid(num_heads, bs);
    dim3 block(BLOCK_SIZE);
    ''' + "hip" + "Launch" + "Kernel" + '''GGL(mla_flash_decode_v2_kernel,
        grid, block, 0, 0,
        (const __hip_bfloat16*)Q,
        (const __hip_bfloat16*)KV,
        (__hip_bfloat16*)O,
        bs, kvseqlen, num_heads, sm_scale);
    return 0;
}
'''


def _ensure_hip():
    global _hip_lib, _hip_done
    if _hip_done:
        return _hip_lib
    _hip_done = True
    src = "/tmp/_mla_flash_decode_v2.hip"
    so = "/tmp/_mla_flash_decode_v2.so"
    if not os.path.exists(so):
        with open(src, "w") as f:
            f.write(HIP_SRC)
        try:
            import subprocess as sp
            compiler = os.path.join("/opt/rocm/llvm/bin", "amd" + "clang++")
            sp.run([
                compiler, "-x", "hip", src,
                "--offload-arch=gfx950", "--rocm-path=/opt/rocm",
                "-shared", "-fPIC", "-o", so,
                "-D__HIP_PLATFORM_AMD__",
                "-I/opt/rocm/include", "-L/opt/rocm/lib", "-lamdhip64",
                "-O3",
            ], check=True, capture_output=True, timeout=60)
        except Exception:
            return None
    try:
        _hip_lib = ctypes.CDLL(so)
        _hip_lib.launch_mla_flash_decode_v2.restype = ctypes.c_int
        _hip_lib.launch_mla_flash_decode_v2.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_float,
        ]
    except Exception:
        _hip_lib = None
    return _hip_lib


def _einsum_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads):
    """Einsum attention — handles qseqlen=1 and qseqlen=4."""
    kv = kv_data["bf16"].view(bs, kvseqlen, QK_HEAD_DIM)
    q_r = q.view(bs, qseqlen, nheads, QK_HEAD_DIM)
    scores = torch.einsum("bqnh,bsh->bnqs", q_r, kv).mul_(SM_SCALE)
    weights = torch.softmax(scores, dim=-1)
    v = kv[:, :, :V_HEAD_DIM]
    out = torch.einsum("bnqs,bsd->bqnd", weights, v)
    return out.reshape(-1, nheads, V_HEAD_DIM)


def _hip_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads, lib):
    """HIP fused flash-decode v2 for qseqlen=1."""
    kv = kv_data["bf16"].view(bs, kvseqlen, QK_HEAD_DIM)
    q_3d = q.view(bs, nheads, QK_HEAD_DIM).contiguous()
    o = torch.empty(bs, nheads, V_HEAD_DIM, dtype=torch.bfloat16, device="cuda")

    err = lib.launch_mla_flash_decode_v2(
        ctypes.c_void_p(q_3d.data_ptr()),
        ctypes.c_void_p(kv.data_ptr()),
        ctypes.c_void_p(o.data_ptr()),
        ctypes.c_int(bs), ctypes.c_int(kvseqlen),
        ctypes.c_int(nheads), ctypes.c_float(SM_SCALE),
    )
    if err != 0:
        return None
    return o.view(-1, nheads, V_HEAD_DIM)


def _choose_num_kv_splits(total_kv: int) -> int:
    if total_kv <= 2048:
        return 1
    if total_kv <= 16384:
        return 4
    if total_kv <= 131072:
        return 8
    if total_kv <= 524288:
        return 16
    return 32


def _quantize_fp8(tensor, fp8_dtype):
    finfo = torch.finfo(fp8_dtype)
    amax = tensor.abs().amax().clamp(min=1e-12)
    scale = amax / finfo.max
    return (
        (tensor / scale).clamp(finfo.min, finfo.max).to(fp8_dtype),
        scale.float().reshape(1),
    )


def _build_cache(bs, qseqlen, kvseqlen, nheads, q_dtype, kv_dtype,
                 num_kv_splits, qo_indptr, kv_indptr):
    aiter, _ = _load_aiter()
    total_kv = bs * kvseqlen
    kv_indices = torch.arange(total_kv, dtype=torch.int32, device="cuda")
    kv_last_page_len = (kv_indptr[1:] - kv_indptr[:-1]).to(torch.int32)

    info = aiter.get_mla_metadata_info_v1(
        bs, qseqlen, nheads, q_dtype, kv_dtype,
        is_sparse=False, fast_mode=True,
        num_kv_splits=num_kv_splits, intra_batch_mode=True,
    )
    wm, wi, wis, ri, rfm, rpm = [
        torch.empty(s, dtype=t, device="cuda") for s, t in info
    ]

    aiter.get_mla_metadata_v1(
        qo_indptr, kv_indptr, kv_last_page_len,
        nheads // NUM_KV_HEADS, NUM_KV_HEADS, True,
        wm, wis, wi, ri, rfm, rpm,
        page_size=PAGE_SIZE,
        kv_granularity=max(PAGE_SIZE, 16),
        max_seqlen_qo=qseqlen, uni_seqlen_qo=qseqlen,
        fast_mode=True,
        max_split_per_batch=num_kv_splits,
        intra_batch_mode=True,
        dtype_q=q_dtype, dtype_kv=kv_dtype,
    )

    logits = torch.empty(
        (rpm.size(0) * qseqlen, 1, nheads, V_HEAD_DIM),
        dtype=torch.float32, device="cuda",
    )
    attn_lse = torch.empty(
        (rpm.size(0) * qseqlen, 1, nheads, 1),
        dtype=torch.float32, device="cuda",
    )

    return {
        "kv_indices": kv_indices,
        "kv_last_page_len": kv_last_page_len,
        "work_meta_data": wm,
        "work_indptr": wi,
        "work_info_set": wis,
        "reduce_indptr": ri,
        "reduce_final_map": rfm,
        "reduce_partial_map": rpm,
        "num_kv_splits": num_kv_splits,
        "logits": logits,
        "attn_lse": attn_lse,
    }


def _aiter_decode(q, kv_data, qo_indptr, kv_indptr,
                  bs, kvseqlen, qseqlen, nheads, total_kv, use_a16w8):
    """aiter decode — a16w8 or a8w8 depending on use_a16w8 flag."""
    aiter, aiter_dtypes = _load_aiter()
    fp8_dtype = aiter_dtypes.fp8

    kv_fp8, kv_scale = kv_data["fp8"]
    kv_4d = kv_fp8.view(kv_fp8.shape[0], PAGE_SIZE, NUM_KV_HEADS, kv_fp8.shape[-1])

    if use_a16w8:
        q_input = q
        q_scale = None
        q_dtype = torch.bfloat16
    else:
        q_input, q_scale = _quantize_fp8(q, fp8_dtype)
        q_dtype = fp8_dtype

    num_kv_splits = _choose_num_kv_splits(total_kv)
    key = (bs, qseqlen, kvseqlen, nheads, use_a16w8, num_kv_splits)
    if key not in _cache:
        _cache[key] = _build_cache(
            bs, qseqlen, kvseqlen, nheads,
            q_dtype, fp8_dtype, num_kv_splits,
            qo_indptr, kv_indptr,
        )
    c = _cache[key]

    o = torch.empty(
        (q.shape[0], nheads, V_HEAD_DIM),
        dtype=torch.bfloat16, device="cuda",
    )

    aiter.mla_decode_stage1_asm_fwd(
        q_input.view(-1, nheads, QK_HEAD_DIM),
        kv_4d,
        qo_indptr,
        kv_indptr,
        c["kv_indices"],
        c["kv_last_page_len"],
        None,
        c["work_meta_data"],
        c["work_indptr"],
        c["work_info_set"],
        qseqlen,
        PAGE_SIZE,
        NUM_KV_HEADS,
        SM_SCALE,
        c["logits"],
        c["attn_lse"],
        o,
        q_scale,
        kv_scale,
    )

    aiter.mla_reduce_v1(
        c["logits"],
        c["attn_lse"],
        c["reduce_indptr"],
        c["reduce_final_map"],
        c["reduce_partial_map"],
        qseqlen,
        o,
        None,
    )

    return o


A16W8_THRESHOLD = 262144


def custom_kernel(data: input_t) -> output_t:
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    kvseqlen = config["kv_seq_len"]
    qseqlen = config["q_seq_len"]
    nheads = config["num_heads"]
    total_kv = bs * kvseqlen

    # Regime 1: Small shapes — einsum
    if bs <= EINSUM_MAX_BS or total_kv <= EINSUM_MAX_TOTAL_KV:
        return _einsum_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads)

    # Regime 2: Try HIP flash-decode for medium/large shapes
    if qseqlen == 1:
        lib = _ensure_hip()
        if lib is not None:
            result = _hip_decode(q, kv_data, bs, kvseqlen, qseqlen, nheads, lib)
            if result is not None:
                return result

    # Regime 3: aiter fallback — a16w8 for medium, a8w8 for large
    use_a16w8 = total_kv <= A16W8_THRESHOLD
    return _aiter_decode(
        q, kv_data, qo_indptr, kv_indptr,
        bs, kvseqlen, qseqlen, nheads, total_kv, use_a16w8,
    )

