 91→    if (sb > 254) sb = 254;
 92→    unsigned char scale_byte = (unsigned char)sb;
 93→
 94→    float quant_scale = exp2f((float)(129 - exp_biased));
 95→    float n0 = v0 * quant_scale;
 96→    float n1 = v1 * quant_scale;
 97→
 98→    auto encode_fp4_ieee = [](float x) -> unsigned char {
 99→        unsigned int qx = __float_as_uint(x);
100→        unsigned int sign = qx & 0x80000000u;
101→        qx ^= sign;
102→        float qx_pos = __uint_as_float(qx);
103→        unsigned char e2m1;
104→        if (qx_pos >= 6.0f) {
105→            e2m1 = 0x7u;
106→        } else if (qx_pos < 1.0f) {
107→            float denormal_x = qx_pos + __uint_as_float(0x4A800000u);
108→            unsigned int du = __float_as_uint(denormal_x) - 0x4A800000u;
109→            e2m1 = (unsigned char)du;
110→        } else {
111→            unsigned int mant_odd = (qx >> 22) & 1u;
112→            qx += 0xC11FFFFFu;
113→            qx += mant_odd;
114→            qx >>= 22;
115→            e2m1 = (unsigned char)qx;
116→        }
117→        e2m1 |= (unsigned char)(sign >> 28);
118→        return e2m1;
119→    };
120→
121→    unsigned char fp4_0 = encode_fp4_ieee(n0);
122→    unsigned char fp4_1 = encode_fp4_ieee(n1);
123→    A_q[row * (K / 2) + grp * (GROUP_SIZE / 2) + lane] = (fp4_1 << 4) | (fp4_0 & 0x0F);
124→
125→    if (lane == 0) {
126→        A_scale_shuffled[shuffle_index(row, grp, sm, sn)] = scale_byte;
127→    }
128→}
