  1→/**
  2→ * Fused MLA Attention Kernel Implementation
  3→ * 
  4→ * FlashAttention-style fused kernel for DeepSeek MLA decode on MI355X.
  5→ * 
  6→ * Architecture:
  7→ * - Grid: (num_heads, batch_size, 1)
  8→ * - Block: (WARP_SIZE, 1, 1) where WARP_SIZE = 64 on MI355X
  9→ * 
 10→ * Each warp processes one query position (qseqlen=1 for decode).
 11→ * Uses online softmax algorithm for numerical stability.
 12→ * 
 13→ * Key optimization: Process KV in tiles (BLOCK_N) to maintain cache locality.
 14→ * V dimension (512) is processed in chunks to fit in shared memory.
 15→ */
 16→
 17→#include "attention_kernels.h"
 18→#include <hip/hip_runtime.h>
 19→#include <hip/hip_fp16.h>
 20→
 21→// MI355X specific constants
 22→#define WARP_SIZE 64
 23→#define MAX_REGS_PER_THREAD 256
 24→
 25→// Use float accumulation for numerical stability
 26→// Process V in chunks to avoid excessive register pressure
 27→#define V_CHUNK_SIZE 64
 28→
 29→/**
 30→ * Online softmax update for FlashAttention.
 31→ * 
 32→ * Given new scores (qk), update running max (m) and sum (l).
 33→ * Returns normalized attention weights.
 34→ * 
 35→ * m_new = max(m_old, max(qk))
 36→ * l_new = exp(m_old - m_new) * l_old + sum(exp(qk - m_new))
 37→ * weights = exp(qk - m_new) / l_new
 38→ */
 39→__device__ __forceinline__ void online_softmax_update(
 40→    float qk,
 41→    float& m,      // running max (inout)
 42→    float& l,      // running sum (inout)
 43→    float& weight  // output weight
 44→) {
 45→    float m_new = fmaxf(m, qk);
 46→    float exp_old = expf(m - m_new);
 47→    float exp_new = expf(qk - m_new);
 48→    l = l * exp_old + exp_new;
 49→    m = m_new;
 50→    weight = exp_new;
 51→}
 52→
 53→/**
 54→ * Fused MLA decode kernel - BF16 version.
 55→ * 
 56→ * Each warp processes one query head for one sequence.
 57→ * Implements FlashAttention-style online softmax.
 58→ * 
 59→ * Memory layout:
 60→ * - Q: [total_q, num_heads, QK_HEAD_DIM] - row-major
 61→ * - KV: [total_kv, NUM_KV_HEADS, QK_HEAD_DIM] - row-major
 62→ * - O: [total_q, num_heads, V_HEAD_DIM] - row-major
 63→ */
 64→__global__ void fused_mla_decode_kernel(
 65→    const __half* __restrict__ q,
 66→    const __half* __restrict__ kv,
 67→    __half* __restrict__ o,
 68→    const int* __restrict__ qo_indptr,
 69→    const int* __restrict__ kv_indptr,
 70→    int batch_size,
 71→    int num_heads,
 72→    float sm_scale
 73→) {
 74→    // Grid: (num_heads, batch_size, 1)
 75→    // Block: (WARP_SIZE, 1, 1)
 76→    
 77→    const int head_idx = blockIdx.x;
 78→    const int batch_idx = blockIdx.y;
 79→    const int lane_id = threadIdx.x;
 80→    
 81→    // Get sequence boundaries
 82→    const int q_start = qo_indptr[batch_idx];
 83→    const int q_end = qo_indptr[batch_idx + 1];
 84→    const int kv_start = kv_indptr[batch_idx];
 85→    const int kv_end = kv_indptr[batch_idx + 1];
 86→    
 87→    const int q_len = q_end - q_start;      // should be 1 for decode
 88→    const int kv_len = kv_end - kv_start;
 89→    
 90→    // For decode, q_len should be 1, but handle general case
 91→    // Each warp processes one query position
 92→    for (int q_pos = 0; q_pos < q_len; ++q_pos) {
 93→        // Q pointer for this query position and head
 94→        const int q_offset = (q_start + q_pos) * num_heads * QK_HEAD_DIM + head_idx * QK_HEAD_DIM;
 95→        const __half* q_ptr = q + q_offset;
 96→        
 97→        // Output pointer
 98→        const int o_offset = (q_start + q_pos) * num_heads * V_HEAD_DIM + head_idx * V_HEAD_DIM;
 99→        __half* o_ptr = o + o_offset;
100→        
101→        // Online softmax state
102→        float m = -INFINITY;  // running max
103→        float l = 0.0f;       // running sum
104→        
105→        // Accumulator for V (process in chunks)
106→        float acc[V_HEAD_DIM];
107→        #pragma unroll
108→        for (int v = 0; v < V_HEAD_DIM; ++v) {
109→            acc[v] = 0.0f;
110→        }
111→        
112→        // Process KV in tiles
113→        // Each thread in warp processes a subset of KV tokens
114→        const int kv_per_thread = (kv_len + WARP_SIZE - 1) / WARP_SIZE;
115→        const int kv_start_lane = lane_id * kv_per_thread;
116→        const int kv_end_lane = min(kv_start_lane + kv_per_thread, kv_len);
117→        
118→        // First pass: compute Q@K^T for this lane's KV tokens
119→        float local_scores[128];  // Max KV tokens per thread
120→        int num_local_kv = 0;
121→        
122→        for (int kv_pos = kv_start_lane; kv_pos < kv_end_lane; ++kv_pos) {
123→            // KV pointer for this position
124→            const int kv_offset = (kv_start + kv_pos) * NUM_KV_HEADS * QK_HEAD_DIM;
125→            const __half* kv_ptr = kv + kv_offset;
126→            
127→            // Compute dot product Q @ K^T
128→            // Q: [QK_HEAD_DIM], K: [QK_HEAD_DIM]
129→            float qk = 0.0f;
130→            #pragma unroll 8
131→            for (int d = 0; d < QK_HEAD_DIM; ++d) {
132→                float q_val = __half2float(q_ptr[d]);
133→                float k_val = __half2float(kv_ptr[d]);
134→                qk += q_val * k_val;
135→            }
136→            qk *= sm_scale;
137→            
138→            local_scores[num_local_kv++] = qk;
139→        }
140→        
141→        // Warp-level reduction to find global max
142→        // First find local max
143→        float local_max = -INFINITY;
144→        for (int i = 0; i < num_local_kv; ++i) {
145→            local_max = fmaxf(local_max, local_scores[i]);
146→        }
147→        
148→        // Warp reduce max
149→        #pragma unroll
150→        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
151→            local_max = fmaxf(local_max, __shfl_xor(local_max, offset));
152→        }
153→        
154→        // Now compute softmax and accumulate V
155→        float lane_sum = 0.0f;
156→        
157→        for (int i = 0; i < num_local_kv; ++i) {
158→            float weight = expf(local_scores[i] - local_max);
159→            lane_sum += weight;
160→            
161→            // Load V and accumulate
162→            int kv_pos = kv_start_lane + i;
163→            const int kv_offset = (kv_start + kv_pos) * NUM_KV_HEADS * QK_HEAD_DIM;
164→            const __half* kv_ptr = kv + kv_offset;
165→            
166→            // V is first V_HEAD_DIM elements of KV
167→            #pragma unroll 8
168→            for (int v = 0; v < V_HEAD_DIM; ++v) {
169→                float v_val = __half2float(kv_ptr[v]);
170→                acc[v] += weight * v_val;
171→            }
172→        }
173→        
174→        // Warp reduce sum
175→        #pragma unroll
176→        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
177→            lane_sum += __shfl_xor(lane_sum, offset);
178→        }
179→        
180→        // Normalize and write output
181→        float inv_sum = 1.0f / lane_sum;
182→        
183→        // Each thread writes a portion of output
184→        const int v_per_thread = (V_HEAD_DIM + WARP_SIZE - 1) / WARP_SIZE;
185→        const int v_start_lane = lane_id * v_per_thread;
186→        const int v_end_lane = min(v_start_lane + v_per_thread, V_HEAD_DIM);
187→        
188→        for (int v = v_start_lane; v < v_end_lane; ++v) {
189→            // Warp-level reduction for acc[v]
190→            float acc_v = acc[v];
191→            #pragma unroll
192→            for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
193→                acc_v += __shfl_xor(acc_v, offset);
194→            }
195→            
196→            // Normalize and store
197→            float out_val = acc_v * inv_sum;
198→            o_ptr[v] = __float2half(out_val);
199→        }
200→    }
201→}
